//! Typed failures produced by repository automation.

use std::io;
use std::path::PathBuf;

use thiserror::Error;

use crate::check::request::VerificationSuite;
use crate::length;
use crate::remote::error;
use crate::source_tree;

/// Result returned by xtask operations.
pub(crate) type Result<T> = std::result::Result<T, Error>;

/// Failures surfaced by xtask commands.
#[derive(Debug, Error)]
pub(crate) enum Error {
    /// Generated source is missing or differs from the Rust declaration.
    #[error("[xtask/types] generated bytes differ at {}; run cargo xtask generate-types", path.display())]
    GeneratedTypeMismatch {
        /// Source that must be generated again.
        path: PathBuf,
    },
    /// A generated directory contains a source the generator does not own.
    #[error("[xtask/types] unexpected generated path {}", path.display())]
    UnexpectedGeneratedType {
        /// Stale or otherwise unexpected path.
        path: PathBuf,
    },
    /// No native npm package exists for the host.
    #[error("[xtask/native] unsupported host {os}/{architecture}")]
    NativeHost {
        /// Host operating system.
        os: String,
        /// Host architecture.
        architecture: String,
    },
    /// An explicit dependency audit mode was requested for another suite.
    #[error(
        "[xtask/check] --dependency-audit is not supported with suite {suite}; select the complete gate or --suite repository"
    )]
    UnsupportedDependencyAudit {
        /// Selected unsupported suite.
        suite: VerificationSuite,
    },
    /// Remote verification failed at a typed runtime boundary.
    #[error("[xtask/check] {source}")]
    Remote {
        /// Original remote verification error.
        source: error::Error,
    },
    /// A shard did not use the required one-based `INDEX/TOTAL` form.
    #[error(
        "[xtask/check] invalid shard `{shard}`; expected one-based INDEX/TOTAL within JavaScript safe integers"
    )]
    InvalidShard {
        /// Rejected argument.
        shard: String,
    },
    /// Sharding was requested without selecting a suite.
    #[error("[xtask/check] --shard is valid only for the browser suite")]
    ShardRequiresSuite,
    /// Sharding was requested for an unsupported suite.
    #[error("[xtask/check] --shard is not supported with suite {suite}")]
    UnsupportedShard {
        /// Selected unsupported suite.
        suite: VerificationSuite,
    },
    /// The workspace root could not be derived from the crate manifest.
    #[error("[xtask/root] could not resolve the workspace root")]
    WorkspaceRoot,
    /// A subprocess could not be started.
    #[error("[xtask/command] could not start `{command}`: {source}")]
    CommandStart {
        /// Human-readable command.
        command: String,
        /// Originating operating-system error.
        source: io::Error,
    },
    /// A subprocess returned a non-success status.
    #[error("[xtask/command] `{command}` failed with status {status}")]
    CommandFailed {
        /// Human-readable command.
        command: String,
        /// Exit code or signal description.
        status: String,
    },
    /// A filesystem operation used by a repository audit failed.
    #[error("[xtask/filesystem] {operation} `{path}` failed: {source}")]
    Filesystem {
        /// Operation being attempted.
        operation: &'static str,
        /// Affected path.
        path: String,
        /// Originating operating-system error.
        source: io::Error,
    },
    /// The source-tree fingerprint failed.
    #[error("[xtask/check] {source}")]
    SourceTree {
        /// Original source-tree fingerprint error.
        source: source_tree::error::Error,
    },
    /// A length audit or the protocol cap ratchet failed.
    #[error("[xtask/check] {source}")]
    Length {
        /// Original length audit error.
        source: length::error::Error,
    },
    /// Rust files exceeded the workspace line limit.
    #[error("[xtask/rust-file-length] files exceed 300 lines:\n{details}")]
    RustFileLength {
        /// Sorted violation report.
        details: String,
    },
}

/// Add typed context to filesystem results without obscuring call sites.
pub(crate) trait FilesystemResult<T> {
    /// Convert an I/O failure into the workspace filesystem contract.
    fn with_filesystem_context(self, operation: &'static str, path: &str) -> Result<T>;
}

impl<T> FilesystemResult<T> for io::Result<T> {
    #[track_caller]
    fn with_filesystem_context(self, operation: &'static str, path: &str) -> Result<T> {
        match self {
            Ok(value) => Ok(value),
            Err(source) => Err(Error::Filesystem {
                operation,
                path: path.to_owned(),
                source,
            }),
        }
    }
}
